const _raw = $input.first().json;
const d = (_raw && typeof _raw === 'object' && _raw.body && typeof _raw.body === 'object') ? _raw.body : _raw;
const name = (d.name || 'Guest').toString().trim();
const service = (d.service || 'consultation').toString();
const date = d.date; // YYYY-MM-DD
const time = d.time || '10:00'; // HH:MM (24h)
const start = new Date(date + 'T' + time + ':00');
if (isNaN(start.getTime())) throw new Error('Invalid date/time. Send date as YYYY-MM-DD and time as HH:MM (24h).');
const end = new Date(start.getTime() + 30 * 60000);
const reminderAt = new Date(start.getTime() - 24 * 3600000);
return [{ json: {
  name: name,
  service: service,
  phone: (d.phone || '').toString(),
  email: (d.email || '').toString(),
  notes: (d.notes || '').toString(),
  eventStart: start.toISOString(),
  eventEnd: end.toISOString(),
  reminderAt: reminderAt.toISOString(),
  receivedAt: new Date().toISOString()
}}];

